local name = 'mods/hd2_hud/hd2_hud_plus'
local engine = rawget(_G, 'stingray')
local app = engine and rawget(engine, 'Application')
local asked, found = pcall(function() return app.can_get('lua', name) end)
if asked and found == false then return { installed = false } end
local loaded, entry = pcall(require, name)
if not loaded or type(entry) ~= 'table' then return { installed = false } end
local started, runtime = pcall(entry.start, _G)
if not started then return { installed = false } end
return { installed = true, runtime = runtime }
